g=grid # currently target test grid saved
# counts of 4s per row and col
rowcnt=[sum(v==4 for v in row) for row in g]
colcnt=[sum(g[i][j]==4 for i in range(len(g))) for j in range(len(g[0]))]
print('row counts',rowcnt,'col counts',colcnt)
mark=set()
for i,row in enumerate(g):
    inds=[j for j,v in enumerate(row) if v==4]
    for a,b in zip(inds,inds[1:]):
        if colcnt[a]<3 or colcnt[b]<3:
            mark.update((i,j) for j in range(a+1,b))
for j in range(len(g[0])):
    inds=[i for i in range(len(g)) if g[i][j]==4]
    for a,b in zip(inds,inds[1:]):
        if rowcnt[a]<3 or rowcnt[b]<3:
            mark.update((i,j) for i in range(a+1,b))
out=[row[:] for row in g]
for i,j in mark: out[i][j]=2
print(sorted(mark))
print('\n'.join(' '.join(map(str,r)) for r in out))
